const updateComment = `-- name: UpdateComment :one
UPDATE project_comments
   SET body = coalesce($1, body),
       mentions = coalesce($2::uuid[], mentions),
       resolved_at = CASE
                       WHEN $3::boolean IS NULL THEN resolved_at
                       WHEN $3::boolean THEN coalesce(resolved_at, now())
                     END,
       resolved_by = CASE
                       WHEN $3::boolean IS NULL THEN resolved_by
                       WHEN $3::boolean THEN coalesce(resolved_by, $4)
                     END
 WHERE id = $5
RETURNING id, tenant_id, project_id, step_key, field_key, parent_id, author_id, body, mentions, resolved_at, resolved_by, created_at, updated_at, deleted_at
`

type UpdateCommentParams struct {
	Body     *string
	Mentions []uuid.UUID
	Resolved *bool
	UserID   *uuid.UUID
	ID       uuid.UUID
}

func (q *Queries) UpdateComment(ctx context.Context, arg UpdateCommentParams) (ProjectComment, error) {
	row := q.db.QueryRow(ctx, updateComment,
		arg.Body,
		arg.Mentions,
		arg.Resolved,
		arg.UserID,
		arg.ID,
	)
	var i ProjectComment
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.ProjectID,
		&i.StepKey,
		&i.FieldKey,
		&i.ParentID,
		&i.AuthorID,
		&i.Body,
		&i.Mentions,
		&i.ResolvedAt,
		&i.ResolvedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
